const prep = $('Prep Meta').first().json;
const j = $input.first().json;

const decode = s => typeof s === 'string'
  ? s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
     .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x2F;/g, '/')
  : s;

const out = { ...prep.prompts };
if (j.translations) {
  prep.fieldNames.forEach((n, i) => { out[n] = decode(j.translations[i].text); });
}

const clientName = prep.clientName || '';
const coreKeyword = prep.coreKeyword || '';

// The core keyword and the client name are kept out of the DeepL payload as
// placeholders and restored here, so neither is ever re-translated.
const CORE = /\{\{\s*CORE_KEYWORD\s*\}\}/g;
const CLIENT = /\{\{\s*CLIENT_NAME\s*\}\}/g;
const lockedBlock = `\n\n<locked_values>\ncore keyword = "${coreKeyword}"\nclient name = "${clientName}"\n</locked_values>\nReproduce both strings above character for character. Never translate, abbreviate or reword either one.`;

for (const key of Object.keys(out)) {
  if (typeof out[key] !== 'string') continue;
  const wanted = /\{\{\s*(CORE_KEYWORD|CLIENT_NAME)\s*\}\}/.test(prep.prompts[key] || '');
  if (!wanted) continue;

  const survived = CORE.test(out[key]) || CLIENT.test(out[key]);
  CORE.lastIndex = 0;
  CLIENT.lastIndex = 0;

  out[key] = out[key].replace(CORE, coreKeyword).replace(CLIENT, clientName);
  if (!survived) out[key] += lockedBlock;
}

return [{ json: { ...out, clientName, coreKeyword } }];

